{"path": "tests/test_users.py", "file_text": "from app.api.handlers import handle_get_user, handle_users_by_ids


def test_get_user_ok():
    assert handle_get_user({"id": "1"}) == (200, {"id": 1, "name": "Ada Lovelace", "email": "ada@example.com"})


def test_get_user_invalid():
    assert handle_get_user({"id": "abc"})[0] == 400


def test_get_user_missing():
    assert handle_get_user({"id": "99"})[0] == 404


def test_users_by_ids_ok():
    assert handle_users_by_ids({"ids": ["3", "1"]}) == (200, {"users": [
        {"id": 1, "name": "Ada Lovelace", "email": "ada@example.com"},
        {"id": 3, "name": "Grace Hopper", "email": "grace@example.com"},
    ]})


def test_users_by_ids_dedupes_and_ignores_unknown():
    assert handle_users_by_ids({"ids": ["1", "1", "99"]}) == (200, {"users": [
        {"id": 1, "name": "Ada Lovelace", "email": "ada@example.com"},
    ]})


def test_users_by_ids_empty_result():
    assert handle_users_by_ids({"ids": ["99"]}) == (200, {"users": []})


def test_users_by_ids_invalid():
    for params in (
        {},
        {"ids": "1"},
        {"ids": []},
        {"ids": ["1"] * 21},
        {"ids": ["1", 2]},
        {"ids": ["abc"]},
    ):
        assert handle_users_by_ids(params) == (400, {"error": "invalid ids"})
"}

